mod common;

use common::Harness;
use serde_json::json;

fn create(h: &mut Harness, name: &str, attributes: serde_json::Value) {
    h.ok(json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes}));
}

fn send(h: &mut Harness, queue: &str, body: &str) -> String {
    h.run(json!({"Command": "SendMessage", "QueueName": queue, "Body": body}))["error"]["code"]
        .as_str()
        .unwrap_or("ok")
        .to_owned()
}

fn max_bytes(h: &mut Harness, queue: &str) -> serde_json::Value {
    h.ok(json!({"Command": "GetQueueAttributes", "QueueName": queue}))["Attributes"]
        ["MaxMessageBytes"]
        .clone()
}

#[test]
fn body_longer_than_limit_is_rejected_and_limit_is_inclusive() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 4}));
    assert_eq!(send(&mut h, "q", "abcd"), "ok");
    assert_eq!(send(&mut h, "q", "abcde"), "InvalidParameterValue");
}

#[test]
fn limit_counts_utf8_bytes() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 3}));
    assert_eq!(send(&mut h, "q", "é"), "ok");
    assert_eq!(send(&mut h, "q", "éé"), "InvalidParameterValue");
}

#[test]
fn limit_rule_comes_before_fifo_rules() {
    let mut h = Harness::new();
    create(&mut h, "q.fifo", json!({"Fifo": true, "MaxMessageBytes": 1}));
    // Without GroupId this would be MissingParameter if rule 2 ran first.
    assert_eq!(send(&mut h, "q.fifo", "ab"), "InvalidParameterValue");
    create(&mut h, "s", json!({"MaxMessageBytes": 1}));
    // A standard queue with GroupId would be UnsupportedOperation otherwise.
    let code = h.err(
        json!({"Command": "SendMessage", "QueueName": "s", "Body": "ab", "GroupId": "g"}),
    );
    assert_eq!(code, "InvalidParameterValue");
}

#[test]
fn queue_lookup_and_body_range_still_come_first() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 1}));
    assert_eq!(send(&mut h, "missing", "ab"), "QueueDoesNotExist");
    assert_eq!(send(&mut h, "q", ""), "InvalidParameterValue");
}

#[test]
fn default_range_and_set_attributes() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    assert_eq!(max_bytes(&mut h, "q"), json!(1024));
    for bad in [json!(0), json!(1025), json!("5"), json!(5.0)] {
        let code = h.err(json!({"Command": "CreateQueue", "QueueName": "x",
            "Attributes": {"MaxMessageBytes": bad}}));
        assert_eq!(code, "InvalidParameterValue");
    }
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
        "Attributes": {"MaxMessageBytes": 2}}));
    assert_eq!(max_bytes(&mut h, "q"), json!(2));
    assert_eq!(send(&mut h, "q", "abc"), "InvalidParameterValue");
}

#[test]
fn create_is_idempotent_only_with_equal_limit() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 10}));
    create(&mut h, "q", json!({"MaxMessageBytes": 10}));
    let code = h.err(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(code, "QueueAlreadyExists");
}

#[test]
fn lowering_limit_keeps_existing_messages() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    assert_eq!(send(&mut h, "q", "abcdef"), "ok");
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
        "Attributes": {"MaxMessageBytes": 1}}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(r["Messages"][0]["Body"], "abcdef");
}

#[test]
fn dead_letter_move_ignores_limit() {
    let mut h = Harness::new();
    create(&mut h, "dlq", json!({"MaxMessageBytes": 1}));
    create(&mut h, "q", json!({"VisibilityTimeout": 0, "DeadLetterQueue": "dlq", "MaxReceiveCount": 1}));
    assert_eq!(send(&mut h, "q", "abcdef"), "ok");
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "dlq"}));
    assert_eq!(r["Messages"][0]["Body"], "abcdef");
}
